void quick(int a[], int l, int r) {
    if (l >= r) return;
    int i = l, j = r, p = a[l];
    while (i < j) {
        while (i < j && a[j] >= p) j--;
        if (i < j) a[i++] = a[j];
        while (i < j && a[i] <= p) i++;
        if (i < j) a[j--] = a[i];
    }
    a[i] = p;
    quick(a, l, i - 1);
    quick(a, i + 1, r);
}

